#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (SQRT_FUN, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

namespace {

// row and column dimensions
constexpr auto r_vec = noarr::vector<'r'>();
constexpr auto c_vec = noarr::vector<'c'>();

// Layout tuning: matrix A is (r x c), with 'c' the inner/contiguous dimension
struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, c_vec ^ r_vec);
} tuning;


// Array initialization: builds a lower-triangular matrix and then
// makes it positive semi-definite via A := A * A^T.
void init_array(auto A) {
	using namespace noarr;

	// All dimensions are square n x n
	std::size_t n = A | get_length<'r'>();

	// First, initialize A to the prescribed lower-triangular form
	//   for i in 0..n-1:
	//     for j in 0..i:   A[i][j] = (-j % n) / n + 1
	//     for j in i+1..n-1: A[i][j] = 0
	//     A[i][i] = 1
	traverser(A).template for_dims<'r'>([&](auto trav_r) {
		auto state_r = trav_r.state();
		std::size_t i = get_index<'r'>(state_r);

		// j in [0, i]  -> length = i + 1
		auto prefix = trav_r.order(slice<'c'>(0, i + 1));
		prefix.for_each([&](auto state_rc) {
			std::size_t j = get_index<'c'>(state_rc);

			int jj = static_cast<int>(j);
			int nn = static_cast<int>(n);

			num_t val = static_cast<num_t>((-jj) % nn) / static_cast<num_t>(nn)
			          + static_cast<num_t>(1);
			A[state_rc] = val;
		});

		// j in [i+1, n) -> length = n - (i+1)
		auto start = i + 1;
		auto len = n - start; // zero when start == n
		auto suffix = trav_r.order(slice<'c'>(start, len));
		suffix.for_each([&](auto state_rc) {
			A[state_rc] = static_cast<num_t>(0);
		});

		// Set diagonal explicitly to 1
		auto diag_state = idx<'r', 'c'>(i, i);
		A[diag_state] = static_cast<num_t>(1);
	});

	// Allocate auxiliary matrix B with the same structure as A
	auto B = noarr::bag(A.structure());

	// Initialize B to zero
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Make A positive semi-definite:
	//   B[r][s] = sum_t A[r][t] * A[s][t]
	// This is A * A^T written in index form.
	traverser(B).for_each([&](auto state_rs) {
		std::size_t r = get_index<'r'>(state_rs);
		std::size_t s = get_index<'c'>(state_rs);

		// views of rows r and s of A, iterated along the column dimension
		auto row_r = A ^ fix<'r'>(r);
		auto row_s = A ^ fix<'r'>(s);

		traverser(row_r, row_s).for_each([&](auto state_t) {
			B[state_rs] += row_r[state_t] * row_s[state_t];
		});
	});

	// Copy B back to A: A := B
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}


// Cholesky factorization kernel:
//
// for i = 0..n-1:
//   for j = 0..i-1:
//     for k = 0..j-1:
//       A[i][j] -= A[i][k]*A[j][k];
//     A[i][j] /= A[j][j];
//
//   for k = 0..i-1:
//     A[i][i] -= A[i][k]*A[i][k];
//   A[i][i] = sqrt(A[i][i]);
//
[[gnu::flatten, gnu::noinline]]
void kernel_cholesky(auto A) {
	using namespace noarr;

	traverser(A).template for_dims<'r'>([&](auto trav_r) {
		auto state_r = trav_r.state();
		std::size_t i = get_index<'r'>(state_r);

		// j < i part: update strictly lower-triangular entries A[i][j]
		if (i > 0) {
			// j in [0, i)  -> length = i
			auto trav_j = trav_r.order(slice<'c'>(0, i));

			trav_j.for_each([&](auto state_ij) {
				std::size_t j = get_index<'c'>(state_ij);

				// Views of rows i and j for the sum over k in [0, j)
				auto row_i_prefix = A ^ fix<'r'>(i) ^ slice<'c'>(0, j);
				auto row_j_prefix = A ^ fix<'r'>(j) ^ slice<'c'>(0, j);

				// A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[j][k]
				traverser(row_i_prefix, row_j_prefix).for_each([&](auto state_k) {
					A[state_ij] -= row_i_prefix[state_k] * row_j_prefix[state_k];
				});

				// A[i][j] /= A[j][j]
				auto diag_j_state = idx<'r', 'c'>(j, j);
				A[state_ij] /= A[diag_j_state];
			});
		}

		// i == j case: update diagonal entry A[i][i]
		auto diag_i_state = idx<'r', 'c'>(i, i);

		if (i > 0) {
			// k in [0, i) -> length = i
			auto row_i_prefix = A ^ fix<'r'>(i) ^ slice<'c'>(0, i);

			// A[i][i] -= sum_{k=0}^{i-1} A[i][k]^2
			traverser(row_i_prefix).for_each([&](auto state_k) {
				A[diag_i_state] -= row_i_prefix[state_k] * row_i_prefix[state_k];
			});
		}
		// For i == 0 the inner loop is empty in the original code; we still
		// apply SQRT_FUN to the current diagonal value.
		A[diag_i_state] = SQRT_FUN(A[diag_i_state]);
	});
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Set lengths for both dimensions of A
	auto set_lengths = noarr::set_length<'r'>(n) ^ noarr::set_length<'c'>(n);

	// Allocate matrix A
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// Initialize A
	init_array(A.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_cholesky(A.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (to stderr) in a layout-agnostic way
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// Print timing (to stdout)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

