#include "cholesky.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	static constexpr auto a_layout = j_vec ^ i_vec; // A: i x j
} tuning;

// initialization function
void init_array(auto A) {
	using namespace noarr;

	// matrix size (A: i x j, square)
	auto n = A | get_length<'i'>();

	// First, initialize A to the given lower-triangular pattern with unit diagonal
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// j from 0 to i (inclusive)
		auto len1 = i + 1;
		trav_i.order(slice<'j'>(0, len1)).template for_dims<'j'>([=](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j = get_index<'j'>(state_ij);

			int n_int = static_cast<int>(n);
			int j_int = static_cast<int>(j);

			num_t value = static_cast<num_t>((-j_int % n_int)) / static_cast<num_t>(n) + static_cast<num_t>(1);
			A[state_ij] = value;
		});

		// j from i+1 to n-1 -> zero
		if (i + 1 < n) {
			auto start = i + 1;
			auto len2 = n - start;
			trav_i.order(slice<'j'>(start, len2)).template for_dims<'j'>([=](auto trav_ij) {
				auto state_ij = trav_ij.state();
				A[state_ij] = static_cast<num_t>(0);
			});
		}

		// Set diagonal element A[i][i] = 1
		auto state_ii = idx<'i', 'j'>(i, i);
		A[state_ii] = static_cast<num_t>(1);
	});

	// Make the matrix positive semi-definite:
	// B = A * A^T, then A = B.

	// Temporary matrix B with the same structure as A
	auto B = noarr::bag(A.structure());

	// Initialize B to zero
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Triple-nested loops:
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	traverser(A).template for_dims<'j'>([&](auto trav_t) {
		auto state_t = trav_t.state();
		auto t = get_index<'j'>(state_t);

		// Column view of A at column t: A[*, t]
		auto col = A.get_ref() ^ fix<'j'>(t);

		traverser(B).template for_dims<'i'>([&](auto trav_r) {
			auto state_r = trav_r.state();
			auto r = get_index<'i'>(state_r);

			// A[r][t]
			num_t val_r = col[idx<'i'>(r)];

			trav_r.for_each([&](auto state_rs) {
				auto s = get_index<'j'>(state_rs);

				// A[s][t]
				num_t val_s = col[idx<'i'>(s)];

				B[state_rs] += val_r * val_s;
			});
		});
	});

	// Copy B back to A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_cholesky(auto A) {
	using namespace noarr;

	// C code:
	// for (i = 0; i < _PB_N; i++) {
	//   for (j = 0; j < i; j++) {
	//     for (k = 0; k < j; k++)
	//       A[i][j] -= A[i][k] * A[j][k];
	//     A[i][j] /= A[j][j];
	//   }
	//   for (k = 0; k < i; k++)
	//     A[i][i] -= A[i][k] * A[i][k];
	//   A[i][i] = SQRT_FUN(A[i][i]);
	// }

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// View of row i
		auto row_i = A.get_ref() ^ fix<'i'>(i);

		// j-loop: 0 <= j < i
		if (i > 0) {
			trav_i.order(slice<'j'>(0, i)).template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j = get_index<'j'>(state_ij);

				// View of row j
				auto row_j = A.get_ref() ^ fix<'i'>(j);

				// k-loop: 0 <= k < j
				if (j > 0) {
					traverser(row_i, row_j)
						.order(slice<'j'>(0, j))
						.for_each([&](auto state_k) {
							// state_k has index k in dimension 'j'
							A[state_ij] -= row_i[state_k] * row_j[state_k];
						});
				}

				// A[i][j] /= A[j][j];
				auto state_jj = idx<'i', 'j'>(j, j);
				A[state_ij] /= A[state_jj];
			});
		}

		// i == j case: update diagonal A[i][i]
		if (i > 0) {
			auto state_ii = idx<'i', 'j'>(i, i);

			// k-loop: 0 <= k < i
			traverser(row_i)
				.order(slice<'j'>(0, i))
				.for_each([&](auto state_k) {
					auto val = row_i[state_k];
					A[state_ii] -= val * val;
				});
		}

		auto state_ii_final = idx<'i', 'j'>(i, i);
		A[state_ii_final] = SQRT_FUN(A[state_ii_final]);
	});
	#pragma endscop
}

} // namespace

