#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// -----------------------------------------------------------------------------
// Problem configuration (replace with benchmark headers if desired)
// -----------------------------------------------------------------------------

using num_t = double;
constexpr std::size_t N = 1024;

// -----------------------------------------------------------------------------
// Noarr layout description
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// A is an N x N matrix, indexed as A[i][j]
// We choose 'i' as the outer (row) dimension and 'j' as the inner (column) dimension.
constexpr auto a_layout = j_vec ^ i_vec; // scalar ^ j_vec ^ i_vec => dims 'i' (outer), 'j' (inner)

// -----------------------------------------------------------------------------
// Initialization
// -----------------------------------------------------------------------------

// Initialize A to the same values as the original C code:
//
// for (i = 0; i < n; i++) {
//   for (j = 0; j <= i; j++)
//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
//   for (j = i+1; j < n; j++)
//     A[i][j] = 0;
//   A[i][i] = 1;
// }
//
// Then make A positive semi-definite by computing B = A * A^T and copying back:
//   B[r][s] = sum_t A[r][t] * A[s][t];
//   A = B;
namespace {

void init_array(auto A_bag) {
	using namespace noarr;

	// n = length in the 'i' dimension (rows)
	std::size_t n = A_bag | get_length<'i'>();

	// First stage: triangular initialization
	//
	// We traverse rows via traverser and handle the j-loop manually,
	// preserving the data layout and semantics.
	noarr::traverser(A_bag).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		for (std::size_t j = 0; j < n; ++j) {
			auto state_ij = state_i + noarr::idx<'j'>(j);

			if (j <= i) {
				// Replicate (DATA_TYPE)(-j % n) / n + 1
				int j_int = static_cast<int>(j);
				int n_int = static_cast<int>(n);
				num_t val =
					static_cast<num_t>((-j_int % n_int)) / static_cast<num_t>(n) +
					static_cast<num_t>(1);
				A_bag[state_ij] = val;
			} else {
				A_bag[state_ij] = static_cast<num_t>(0);
			}
		}

		// Ensure diagonal is exactly 1, as in the original code
		auto state_ii = state_i + noarr::idx<'j'>(i);
		A_bag[state_ii] = static_cast<num_t>(1);
	});

	// Second stage: Make the matrix positive semi-definite
	//
	// Allocate a temporary matrix B with the same structure as A.
	auto B_bag = noarr::make_bag(A_bag.structure());

	// Initialize B[r][s] = 0
	noarr::traverser(B_bag).for_each([&](auto state) {
		B_bag[state] = static_cast<num_t>(0);
	});

	// Accumulate B[r][s] += A[r][t] * A[s][t] for all t
	for (std::size_t t = 0; t < n; ++t) {
		noarr::traverser(B_bag).for_each([&](auto state) {
			std::size_t r = noarr::get_index<'i'>(state);
			std::size_t s = noarr::get_index<'j'>(state);

			auto state_r_t = noarr::idx<'i', 'j'>(r, t);
			auto state_s_t = noarr::idx<'i', 'j'>(s, t);

			B_bag[state] += A_bag[state_r_t] * A_bag[state_s_t];
		});
	}

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A_bag, B_bag).for_each([&](auto state) {
		A_bag[state] = B_bag[state];
	});
}

// -----------------------------------------------------------------------------
// Cholesky kernel
// -----------------------------------------------------------------------------

// Original kernel:
//
// for (i = 0; i < _PB_N; i++) {
//   // j < i
//   for (j = 0; j < i; j++) {
//     for (k = 0; k < j; k++) {
//       A[i][j] -= A[i][k] * A[j][k];
//     }
//     A[i][j] /= A[j][j];
//   }
//   // i == j case
//   for (k = 0; k < i; k++) {
//     A[i][i] -= A[i][k] * A[i][k];
//   }
//   A[i][i] = SQRT_FUN(A[i][i]);
// }

[[gnu::flatten, gnu::noinline]]
void kernel_cholesky(auto A_bag) {
	using namespace noarr;

#pragma scop
	// Traverse the outer loop over i using a Noarr traverser.
	noarr::traverser(A_bag).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		// Inner loops over j and k are implemented explicitly, since they
		// reuse the same 'j' dimension for both j and k.
		// This preserves the exact computation sequence of the original code.

		// j < i
		for (std::size_t j = 0; j < i; ++j) {
			auto state_ij = state_i + noarr::idx<'j'>(j);

			for (std::size_t k = 0; k < j; ++k) {
				auto state_ik = state_i + noarr::idx<'j'>(k);
				auto state_jk = noarr::idx<'i', 'j'>(j, k);

				A_bag[state_ij] -= A_bag[state_ik] * A_bag[state_jk];
			}

			auto state_jj = noarr::idx<'i', 'j'>(j, j);
			A_bag[state_ij] /= A_bag[state_jj];
		}

		// i == j case (diagonal update)
		auto state_ii = state_i + noarr::idx<'j'>(i);

		for (std::size_t k = 0; k < i; ++k) {
			auto state_ik = state_i + noarr::idx<'j'>(k);
			A_bag[state_ii] -= A_bag[state_ik] * A_bag[state_ik];
		}

		A_bag[state_ii] = static_cast<num_t>(std::sqrt(A_bag[state_ii]));
	});
#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Set lengths for both dimensions 'i' and 'j'
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// Allocate A as an n x n matrix
	auto A = noarr::make_bag(noarr::scalar<num_t>() ^ a_layout ^ set_lengths);

	// Initialize data
	init_array(A.get_ref());

	// Measure execution time of the kernel
	auto start = std::chrono::high_resolution_clock::now();

	kernel_cholesky(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print the resulting matrix (to exercise all live-out data)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Hoist 'i' as the outer dimension for nicer printing
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing (seconds) to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
