#include "defines.hpp"

// include benchmark-specific definitions
#include "cholesky.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec); // rows: 'i', columns: 'j' (row-major)
} tuning;

// Array initialization.
void init_array(auto A) {
	using namespace noarr;

	// Matrix size (N x N)
	std::size_t n = A | get_length<'i'>();

	// ------------------------------------------------------------------
	// First: build a lower-triangular matrix A, then zero upper part
	// ------------------------------------------------------------------
	noarr::traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = noarr::get_index<'i'>(state_i);

		// j = 0 .. i : A[i][j] = (-j % n) / n + 1
		trav_i.order(noarr::slice<'j'>(0, i + 1)).for_each([=](auto s_ij) {
			std::size_t j = noarr::get_index<'j'>(s_ij);

			auto num = -static_cast<long long>(j) % static_cast<long long>(n);
			num_t val = static_cast<num_t>(num) / static_cast<num_t>(n) + static_cast<num_t>(1);

			A[s_ij] = val;
		});

		// j = i+1 .. n-1 : A[i][j] = 0
		if (i + 1 < n) {
			trav_i.order(noarr::slice<'j'>(i + 1, n - (i + 1))).for_each([=](auto s_ij) {
				A[s_ij] = static_cast<num_t>(0);
			});
		}

		// Set diagonal to 1
		A[noarr::idx<'i', 'j'>(i, i)] = static_cast<num_t>(1);
	});

	// ------------------------------------------------------------------
	// Make the matrix positive semi-definite:
	//   B = A * A^T, then copy B back into A
	//   B[r][s] = sum_t A[r][t] * A[s][t]
	// ------------------------------------------------------------------

	auto B = noarr::bag(
		noarr::scalar<num_t>()
		^ tuning.a_layout
		^ noarr::set_length<'i', 'j'>(n, n));

	// Initialize B to zero
	noarr::traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Triple loop: t outer, then r, then s
	noarr::traverser(A).template for_dims<'j'>([&](auto trav_t) {
		auto state_t = trav_t.state();
		std::size_t t = noarr::get_index<'j'>(state_t);

		noarr::traverser(B).for_each([&](auto state_rs) {
			std::size_t r = noarr::get_index<'i'>(state_rs);
			std::size_t s = noarr::get_index<'j'>(state_rs);

			auto state_rt = noarr::idx<'i', 'j'>(r, t);
			auto state_st = noarr::idx<'i', 'j'>(s, t);

			B[state_rs] += A[state_rt] * A[state_st];
		});
	});

	// Copy B back into A
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// Main computational kernel (Cholesky factorization, in-place on A).
[[gnu::flatten, gnu::noinline]]
void kernel_cholesky(auto A) {
	using namespace noarr;

	// Outer loop over i
	noarr::traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = noarr::get_index<'i'>(state_i);

		// --------------------------------------------------------------
		// First: for j = 0 .. i-1
		//   for k = 0 .. j-1:
		//     A[i][j] -= A[i][k] * A[j][k];
		//   A[i][j] /= A[j][j];
		// --------------------------------------------------------------
		if (i > 0) {
			// j in [0, i)
			trav_i.order(noarr::slice<'j'>(0, i)).for_each([=](auto state_ij) {
				std::size_t j = noarr::get_index<'j'>(state_ij);

				// k-loop: k = 0 .. j-1
				if (j > 0) {
					// Views of row i and row j
					auto row_i = A.get_ref() ^ noarr::fix<'i'>(i);
					auto row_j = A.get_ref() ^ noarr::fix<'i'>(j);

					noarr::traverser(row_i, row_j)
						.order(noarr::slice<'j'>(0, j))
						.for_each([=](auto state_k) {
							// state_k carries 'j' as the k-index
							A[state_ij] -= row_i[state_k] * row_j[state_k];
						});
				}

				// Divide by A[j][j]
				auto diag_j_state = noarr::idx<'i', 'j'>(j, j);
				A[state_ij] /= A[diag_j_state];
			});
		}

		// --------------------------------------------------------------
		// Then: diagonal update
		//   for k = 0 .. i-1:
		//     A[i][i] -= A[i][k] * A[i][k];
		//   A[i][i] = sqrt(A[i][i]);
		// --------------------------------------------------------------
		auto diag_state = noarr::idx<'i', 'j'>(i, i);

		if (i > 0) {
			auto row_i = A.get_ref() ^ noarr::fix<'i'>(i);

			noarr::traverser(row_i)
				.order(noarr::slice<'j'>(0, i))
				.for_each([=](auto state_k) {
					A[diag_state] -= row_i[state_k] * row_i[state_k];
				});
		}

		A[diag_state] = SQRT_FUN(A[diag_state]);
	});
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// single matrix A (n x n)
	auto set_lengths = noarr::set_length<'i', 'j'>(n, n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_cholesky(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results to stderr (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

