using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto A) {
	using namespace noarr;

	std::size_t n = A | get_length<'i'>();

	// Initial lower-triangular matrix A
	// for (i = 0; i < n; i++)
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		num_t value = static_cast<num_t>(0);

		if (j <= i) {
			long long j_ll = static_cast<long long>(j);
			long long n_ll = static_cast<long long>(n);
			long long mod = (-j_ll) % n_ll;
			value = static_cast<num_t>(mod) / static_cast<num_t>(n) + static_cast<num_t>(1);
		} else {
			value = static_cast<num_t>(0);
		}

		A[state] = value;
	});

	// Set the diagonal to 1 explicitly (matches original final assignment)
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto si = trav_i.state();
		std::size_t i = get_index<'i'>(si);
		A[idx<'i', 'j'>(i, i)] = static_cast<num_t>(1);
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t];  A = B

	// Temporary matrix B with the same layout as A
	auto B_unique = noarr::bag(A.structure());
	auto B = B_unique.get_ref();

	// for (r = 0; r < n; ++r)
	//   for (s = 0; s < n; ++s)
	//     B[r][s] = 0;
	traverser(B).for_each([=](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	traverser(A).template for_dims<'j'>([=](auto trav_t) {
		auto st = trav_t.state();
		std::size_t t = get_index<'j'>(st);

		traverser(B).for_each([=](auto state_rs) {
			auto [r, s] = get_indices<'i', 'j'>(state_rs);

			B[state_rs] +=
				A[idx<'i', 'j'>(r, t)] *
				A[idx<'i', 'j'>(s, t)];
		});
	});

	// for (r = 0; r < n; ++r)
	//   for (s = 0; s < n; ++s)
	//     A[r][s] = B[r][s];
	traverser(A, B).for_each([=](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_cholesky(auto A) {
	using namespace noarr;

	std::size_t n = A | get_length<'i'>();

	// Original kernel:
	// for (i = 0; i < _PB_N; i++) {
	//   for (j = 0; j < i; j++) {
	//     for (k = 0; k < j; k++) {
	//       A[i][j] -= A[i][k] * A[j][k];
	//     }
	//     A[i][j] /= A[j][j];
	//   }
	//   for (k = 0; k < i; k++) {
	//     A[i][i] -= A[i][k] * A[i][k];
	//   }
	//   A[i][i] = SQRT_FUN(A[i][i]);
	// }

	#pragma scop
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto si = trav_i.state();
		std::size_t i = get_index<'i'>(si);
		auto diag_state = idx<'i', 'j'>(i, i);

		// Handle j < i part
		if (i > 0) {
			// for (j = 0; j < i; j++)
			trav_i.order(noarr::slice<'j'>(0, i)).for_each([=](auto state_ij) {
				auto [ii, j] = get_indices<'i', 'j'>(state_ij);

				// for (k = 0; k < j; k++)
				if (j > 0) {
					auto row_i = A ^ noarr::fix<'i'>(ii);
					auto row_j = A ^ noarr::fix<'i'>(j);

					traverser(row_i, row_j)
						.order(noarr::slice<'j'>(0, j))
						.for_each([=](auto state_k) {
							A[state_ij] -= row_i[state_k] * row_j[state_k];
						});
				}

				// A[i][j] /= A[j][j];
				A[state_ij] /= A[idx<'i', 'j'>(j, j)];
			});
		}

		// i == j case: diagonal update
		if (i > 0) {
			auto row_i = A ^ noarr::fix<'i'>(i);

			// for (k = 0; k < i; k++)
			traverser(row_i)
				.order(noarr::slice<'j'>(0, i))
				.for_each([=](auto state_k) {
					num_t val = row_i[state_k];
					A[diag_state] -= val * val;
				});
		}

		// A[i][i] = SQRT_FUN(A[i][i]);
		A[diag_state] = SQRT_FUN(A[diag_state]);
	});
	#pragma endscop
}

